  @Override public void onCreate(Bundle b){if(!getPackageName().endsWith(".test"))throw new IllegalStateException("Isolated test required");documents.set(0);heads.set(0);failHead=false;nextDraft="";getSharedPreferences("chat",0).edit().clear().putBoolean("pageMode",true).putBoolean("webNotificationAsked",true).putBoolean("networkConfigured",true).putString("networkMode","external").putBoolean("requireExternalVpn",false).putString("conversation",ORIGIN+"c/one").commit();super.onCreate(b);handler.postDelayed(()->waitFor("Initial fixture is usable",()->!session.navigating&&session.entries.length()==2&&session.networkReady,60,()->preserve()),100);}
