  void scope(){session.pageMemory.capture(()->js("document.querySelector('textarea').value='';({ok:true})",r->{String old=session.appliedIdentity;session.appliedIdentity="changed-network-profile";session.pageMemory.restorePending=true;session.pageMemory.restore(remote.getUrl(),session.navigationEpoch);handler.postDelayed(()->js("({draft:document.querySelector('textarea').value})",p->{check("Page memory does not restore across network profiles",p.optString("draft").isEmpty());session.appliedIdentity=old;mobileNavigation();}),250);}));}
